[
  {
    "name": "rootless SDN (bridge, publish, firewall, namespace isolation)",
    "level": "production-ready",
    "evidence": "8 chaos scenarios kill the holder/control/slirp and assert recovery; namespace isolation validated live with real packets through the installed nft chain (AGENTS.md, v0.40.0)"
  },
  {
    "name": "container lifecycle (run/ps/stop/rm/exec/logs)",
    "level": "stable",
    "evidence": "docs/cli-stability.md pins the verbs, flags, exit codes and inspect JSON; ~200 checks in scripts/e2e.sh run them against the real binary"
  },
  {
    "name": "manifest schema (apiVersion delonix.io/v1)",
    "level": "stable",
    "evidence": "generated from the code (ADR-0007) with a test asserting the published docs/schema/v1/delonix.json IS the generated one; scripts/schema-diff.sh compares field by field between tags"
  },
  {
    "name": "exit-code classes",
    "level": "stable",
    "evidence": "contract in docs/cli-stability.md since v0.49.0; cmd/exitcode.rs maps from the error TYPE with an exhaustive match, and e2e.sh asserts numeric classes"
  },
  {
    "name": "image pull/build (OCI)",
    "level": "stable",
    "evidence": "digest verified on manifest AND blobs (registry.rs); resumable downloads with a live-validated cut connection; e2e.sh covers pull/build/export"
  },
  {
    "name": "declarative stack (plan/apply/destroy/history/rollback)",
    "level": "preview",
    "evidence": "three-way diff with no state file; chaos scenarios stack_converge, stack_netroute and stack_partial_apply; history/rollback landed 2026-08-25 and are listed NOT stable in docs/cli-stability.md"
  },
  {
    "name": "CRI (serves a kubelet)",
    "level": "preview",
    "evidence": "docs/cri-conformance.md — critest, a published number with the suite version, the engine version and the date next to it"
  },
  {
    "name": "microVMs (cloud-hypervisor, libvirt)",
    "level": "preview",
    "evidence": "live-validated boot, snapshot and restore on both backends; the vm group is listed NOT stable in docs/cli-stability.md"
  },
  {
    "name": "docker-compose.yml (native)",
    "level": "preview",
    "evidence": "validated end-to-end with Postgres + app, depends_on honouring a real healthcheck; the keys it does NOT support are documented, not silent"
  },
  {
    "name": "Docker Engine API",
    "level": "experimental",
    "evidence": "`serve docker-api --matrix` publishes served/refused/missing with the version; of the 21 routes real tooling calls, 8 are refused — including the pull"
  },
  {
    "name": "Proxmox VM backend",
    "level": "experimental",
    "evidence": "ADR-0008; crates/delonix-proxmox/tests/live.rs runs against a real node, and skips loudly without one"
  },
  {
    "name": "TrueNAS storage provisioning",
    "level": "experimental",
    "evidence": "ADR-0009; chaos scenario truenas_destroy queries the NAS over HTTP instead of trusting what the CLI printed"
  },
  {
    "name": "fleet management (node add/cordon/drain)",
    "level": "experimental",
    "evidence": "DOES NOT EXIST — ADR-0010 is Rejected (2026-08-10). Reopening needs a successor ADR naming the concrete consumer, never a command"
  }
]

